import random
random.seed(7)
target = "(((((((((((........)))).((...............))....(((((.......))))))))))))....(((((((..((((........))))(((.............)))....(((((.......))))))))))))....(((((((..((((........))))((((((.......))))))....(((((.......))))))))))))....(((((((..((((........))))((((((.......))))))....(((((.......))))))))))))....(((((((..((((........))))((((((.......))))))....(((((.......))))))))))))...."
n = len(target)
stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

# Analyze structure into helices (consecutive (i,j) pairs)
# Group base pairs into helices
pair_set = set()
for i in range(n):
    if i in pairs and i < pairs[i]:
        pair_set.add((i, pairs[i]))

# Build helices by walking
helices = []
used = set()
for i in sorted([p for p in pair_set]):
    if i in used:
        continue
    # extend helix from (i, pairs[i])
    j = pairs[i]
    helix = [(i,j)]
    used.add(i)
    k = i+1
    while k in pairs and pairs[k] == j-1 and k not in used:
        helix.append((k, pairs[k]))
        used.add(k)
        j = pairs[k]
        k += 1
    helices.append(helix)

# For each helix, assign a strong pattern: alternate G/C and C/G
seq = ['A']*n
for hi, helix in enumerate(helices):
    # alternate direction each helix to avoid cross-helix GC complementarity
    for k, (i,j) in enumerate(helix):
        if hi % 2 == 0:
            if k % 2 == 0:
                seq[i], seq[j] = 'G','C'
            else:
                seq[i], seq[j] = 'C','G'
        else:
            if k % 2 == 0:
                seq[i], seq[j] = 'C','G'
            else:
                seq[i], seq[j] = 'G','C'

# Loops: hairpin loops use A-rich (no G to avoid stable tetraloops mismatch), but with some U
# For unpaired positions, fill with A predominantly, but break runs of G in adjacent helices
for i in range(n):
    if i not in pairs:
        seq[i] = 'A'

s = ''.join(seq)
print(s)
print("LEN", len(s))
